package main

import (
    "bytes"
    "os/exec"
)

func getLsResult(dirPath string) string {
    // Sanitize the input directory path
    if dirPath == "" || containsInvalidChars(dirPath) {
        return ""
    }

    cmd := exec.Command("ls", "-l", dirPath)

    var out bytes.Buffer
    var stderr bytes.Buffer

    cmd.Stdout = &out
    cmd.Stderr = &stderr

    err := cmd.Run()
    if err != nil {
        return ""
    }

    return out.String() + stderr.String()
}

// Helper function to check for invalid characters in the directory path
func containsInvalidChars(path string) bool {
    // Add any characters that could be used for command injection
    for _, c := range path {
        if c == ';' || c == '|' || c == '&' || c == '$' || c == '`' || c == '\\' {
            return true
        }
    }
    return false
}

